/// <summary>
/// reportDiscrepancy's request, from picking. Reason: SHORT_PICK, DAMAGED, WRONG_ITEM, OTHER.
/// The server decides whether to create a TRIGGERED count.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountDiscrepancyRequest
{
    DataAreaId dataAreaId;
    str        userId;
    str        deviceId;
    str        warehouseId;
    str        locationId;
    str        itemNumber;
    str        reason;
    str        note;

}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('UserId')]
public str parmUserId(str _value = userId)
{
    userId = _value;
    return userId;
}

[DataMemberAttribute('DeviceId')]
public str parmDeviceId(str _value = deviceId)
{
    deviceId = _value;
    return deviceId;
}

[DataMemberAttribute('WarehouseId')]
public str parmWarehouseId(str _value = warehouseId)
{
    warehouseId = _value;
    return warehouseId;
}

[DataMemberAttribute('LocationId')]
public str parmLocationId(str _value = locationId)
{
    locationId = _value;
    return locationId;
}

[DataMemberAttribute('ItemNumber')]
public str parmItemNumber(str _value = itemNumber)
{
    itemNumber = _value;
    return itemNumber;
}

[DataMemberAttribute('Reason')]
public str parmReason(str _value = reason)
{
    reason = _value;
    return reason;
}

[DataMemberAttribute('Note')]
public str parmNote(str _value = note)
{
    note = _value;
    return note;
}
